package com.masaakis.security;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.slf4j.MDC;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.UUID;
@Component public class RequestMetadataFilter extends OncePerRequestFilter{@Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String supplied=r.getHeader("X-Request-Id");String id=supplied!=null&&supplied.matches("[A-Za-z0-9_-]{8,80}")?supplied:UUID.randomUUID().toString();s.setHeader("X-Request-Id",id);if(r.getRequestURI().startsWith("/api/auth/")||r.getRequestURI().startsWith("/api/admin/")||r.getRequestURI().startsWith("/api/table/"))s.setHeader("Cache-Control","no-store");try(MDC.MDCCloseable ignored=MDC.putCloseable("requestId",id)){c.doFilter(r,s);}}
}
